mapper.select:
SELECT a.device_mete_id, e.cruise_time, b.cruise_type, h.dict_note as cruise_type_name, e.instance_name, g.c_type, i.dict_note AS c_type_name, f.result_num, f.identify_result, j.dict_note AS identify_result_name, f.cruise_result, z.dict_note as cruise_result_name, f.picpath as picPath, a.mete_type, m.dict_note as mete_type_name, a.meter_type, n.dict_note as meter_type_name FROM t_cruise_task_result_detail e LEFT JOIN t_cruise_data_result f ON e.cruise_result_id = f.cruise_result_id LEFT JOIN t_cruise_point_instance b ON b.instance_id = e.instance_id LEFT JOIN t_std_devicemete a on a.device_mete_id = b.device_mete_id LEFT JOIN t_cruise_result g ON e.task_result_id = g.task_result_id LEFT JOIN t_dict_business h ON b.cruise_type = h.dict_code AND h.col_name = "cruise_type" LEFT JOIN t_dict_business i ON g.c_type = i.dict_code AND i.col_name = "plan_type" LEFT JOIN t_dict_business j ON f.identify_result = j.dict_code AND j.col_name = "identify_result" LEFT JOIN t_dict_business z ON f.cruise_result=z.dict_code AND z.col_name="cruise_result" LEFT JOIN t_dict_business m ON m.dict_code = a.mete_type AND m.col_name="mete_type" LEFT JOIN t_dict_business n ON n.dict_code = a.meter_type AND n.col_name="meter_type" WHERE 1 = 1 and b.device_id IN
#{deviceIds,jdbcType=BIGINT}
and e.cruise_time between #{startTime,jdbcType=TIMESTAMP} and #{endTime,jdbcType=TIMESTAMP} and g.c_type = #{cType, jdbcType=INTEGER} and a.mete_type = #{meteType, jdbcType=VARCHAR} and a.meter_type = #{meterType, jdbcType=INTEGER} and e.instance_name LIKE CONCAT('%',#{instanceName, jdbcType=VARCHAR},'%') ORDER BY e.cruise_time DESC

SELECT e.end_time, g.c_type, i.dict_note AS cTypeName, b.cruise_type, h.dict_note AS cruiseTypeName, f.identify_result, j.dict_note AS identifyResultName, f.result_num, f.cruise_result, z.dict_note as 'cruiseResultName', f.picpath, ( CASE WHEN ISNULL(a.mete_name) AND ISNULL(y.inspection_name) AND ISNULL(x.preset_name) THEN '' WHEN ISNULL(a.mete_name) AND ISNULL(y.inspection_name) THEN x.preset_name WHEN ISNULL(a.mete_name) AND ISNULL(x.preset_name) THEN y.inspection_name WHEN ISNULL(y.inspection_name) AND ISNULL(x.preset_name) THEN a.mete_name WHEN ISNULL(y.inspection_name) THEN CONCAT( a.mete_name, ' /', x.preset_name ) WHEN ISNULL(x.preset_name) THEN CONCAT( a.mete_name, ' /', y.inspection_name ) END ) AS cruise_name
FROM t_std_devicemete a LEFT JOIN t_cruise_point_instance b ON a.device_mete_id = b.device_mete_id LEFT JOIN t_dict_business h ON b.cruise_type = h.dict_code AND h.col_name = "cruise_type" LEFT JOIN t_cruise_task_result_detail e ON b.instance_id = e.instance_id LEFT JOIN t_cruise_data_result f ON e.cruise_result_id = f.cruise_result_id LEFT JOIN t_dict_business j ON f.identify_result = j.dict_code AND j.col_name = "identify_result" LEFT JOIN t_cruise_result g ON e.task_result_id = g.task_result_id LEFT JOIN t_dict_business i ON g.c_type = i.dict_code AND i.col_name = "plan_type" LEFT JOIN t_camera_preset x ON b.cruise_id=x.preset_id LEFT JOIN t_robot_inspection y ON b.cruise_id=y.inspection_id LEFT JOIN t_dict_business z ON f.cruise_result=z.dict_code AND z.col_name="cruise_result" WHERE a.device_mete_id= #{deviceMeteId,jdbcType=BIGINT}
and e.end_time between #{startDate,jdbcType=TIMESTAMP} and #{endDate,jdbcType=TIMESTAMP} and g.c_type = #{cType, jdbcType=INTEGER} and b.cruise_type = #{cruiseType, jdbcType=INTEGER} ORDER BY e.end_time DESC

SELECT *FROM ( SELECT a.instance_id, b.device_mete_id, a.cruise_time as update_time, d.picpath, d.cruise_result, d.identify_result FROM t_cruise_task_result_detail a,t_cruise_point_instance b,t_cruise_data_result d WHERE 1 = 1 and a.instance_id = b.instance_id and a.cruise_result_id = d.cruise_result_id and a.cruise_result_id IN
#{cruiseResultId,jdbcType=VARCHAR}
ORDER BY cruise_time DESC LIMIT 999999 )as bigTable GROUP BY bigTable.device_mete_id
